! Typed-handle wrappers, included into the module contains section.

    function hipblasCreate_typed(handle) result(Create)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(hipblasHandle_t) :: handle
      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: Create
      Create = hipblasCreate_(handle%ptr)
    end function hipblasCreate_typed

    function hipblasDestroy_typed(handle) result(Destroy)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(hipblasHandle_t), value :: handle
      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: Destroy
      Destroy = hipblasDestroy_(handle%ptr)
    end function hipblasDestroy_typed

    function hipblasGetVersion_typed(handle, version) result(GetVersion)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(hipblasHandle_t), value :: handle
      integer(c_int) :: version
      integer(kind(HIPBLAS_STATUS_SUCCESS)) :: GetVersion
      GetVersion = hipblasGetVersion_(handle%ptr, version)
    end function hipblasGetVersion_typed

